def C(k,v,ev=(),status='observed',refs=(),why='Documentary observation from captured primary content; independent adjudication pending.'):
 aid=r['identity']['id'];return dict(claim_id=f'{aid}.{k}',status=status,value=v,context=sc[str(aid)],evidence=list(ev),supporting_claim_refs=[f'{aid}.{x}' for x in refs],rationale=why)
def start(aid,identity,purpose,ev):
 global r
 r=next(x for x in rs if x['identity']['id']==aid)
 for path,c in p.claims(r):
  c.update(context=sc[str(aid)],status='unknown',rationale='Checked captured primary sources did not establish this condition for the stated interface and account path. Silence is not a negative finding.')
 for env in ['testing','production']:r['credential_eligibility'][env]['context']=sc[str(aid)]
 r['identity']['resolution']=C('identity',identity,ev);r['purpose']=C('purpose',purpose,ev)
 for coll in [r['auth'],r['api_surface']['protocols'],r['api_surface']['resource_groups']]:coll.update(coverage_status='partial',notes='Bounded captured-source coverage only; no completeness or operational success claim.')
def identity(aid,ident,purp,locs):
 global r
 r=next(x for x in rs if x['identity']['id']==aid);start(aid,ident,purp,[E(*x) for x in locs])
