def P(k,v,ev):r['api_surface']['protocols']['items'].append(C('api.protocol.'+k,v,ev))
def G(k,v,ev):r['api_surface']['resource_groups']['items'].append(C('api.group.'+k,v,ev))
def docs(ev):r['api_surface']['public_documentation']=C('api.public_documentation',True,ev)
def L(env,key,v,ev,why,status='observed'):r['credential_eligibility'][env][key]=C(env+'.'+key,v,ev,status=status,why=why)
def M(name,ev,source,scope,server=None,repo=None):
 op=C('mcp.server.operational',None,status='not_researched',why='No server connection or tool invocation attempted; docs do not demonstrate operational behavior.')
 r['mcp']['entries']=[C('mcp.server',dict(origin='official',name=name,source_url=caps[source]['spec']['url'],repository_url=repo,server_url=server,scope=scope,operational_check=op),ev)]
 r['mcp']['discovery']=C('mcp.discovery','found',ev)
def finish(breadth,reason,workflow,blockers,nexts,ev,refs):
 gs=r['api_surface']['resource_groups']['items'];r['api_surface']['breadth']=C('api.breadth',breadth,[e for g in gs for e in g['evidence']],'inferred',[g['claim_id'].split('.',1)[1] for g in gs],reason)
 r['buildability']=C('buildability',dict(verdict='conditional',scope=workflow,blockers=blockers,next_steps=nexts),ev,'inferred',['identity']+refs,'Feasibility inference from the cited interfaces and requirements; no credentials obtained, integration built, or operations tested.')

